class Gradebook:
    def __init__(self):
        self.students = {}
        self.assignments = {}
    
    def add_student(self, name):
        if name in self.students:
            raise ValueError("Student already exists")
        self.students[name] = {}
    
    def add_assignment(self, name, max_points):
        if name in self.assignments:
            raise ValueError("Assignment already exists")
        if not isinstance(max_points, (int, float)) or max_points <= 0:
            raise ValueError("Max points must be a positive number")
        self.assignments[name] = max_points
    
    def record(self, student, assignment, points):
        if student not in self.students:
            raise KeyError("Unknown student")
        if assignment not in self.assignments:
            raise KeyError("Unknown assignment")
        if not isinstance(points, (int, float)) or points < 0 or points > self.assignments[assignment]:
            raise ValueError("Points must be between 0 and max points")
        self.students[student][assignment] = points
    
    def score(self, student, assignment):
        if student not in self.students or assignment not in self.students[student]:
            return None
        return self.students[student][assignment]

if __name__ == "__main__":
    # Test cases
    gradebook = Gradebook()
    
    # Test add_student
    gradebook.add_student("Alice")
    gradebook.add_student("Bob")
    
    try:
        gradebook.add_student("Alice")  # Should raise ValueError
        assert False, "Should have raised ValueError"
    except ValueError:
        pass  # Expected
    
    # Test add_assignment
    gradebook.add_assignment("Homework 1", 100)
    gradebook.add_assignment("Exam 1", 200)
    
    try:
        gradebook.add_assignment("Homework 1", 100)  # Should raise ValueError
        assert False, "Should have raised ValueError"
    except ValueError:
        pass  # Expected
    
    try:
        gradebook.add_assignment("Homework 2", -10)  # Should raise ValueError
        assert False, "Should have raised ValueError"
    except ValueError:
        pass  # Expected
    
    try:
        gradebook.add_assignment("Homework 3", 0)  # Should raise ValueError
        assert False, "Should have raised ValueError"
    except ValueError:
        pass  # Expected
    
    # Test record
    gradebook.record("Alice", "Homework 1", 85)
    gradebook.record("Bob", "Homework 1", 92)
    
    try:
        gradebook.record("Charlie", "Homework 1", 85)  # Should raise KeyError
        assert False, "Should have raised KeyError"
    except KeyError:
        pass  # Expected
    
    try:
        gradebook.record("Alice", "Homework 2", 85)  # Should raise KeyError
        assert False, "Should have raised KeyError"
    except KeyError:
        pass  # Expected
    
    try:
        gradebook.record("Alice", "Homework 1", -5)  # Should raise ValueError
        assert False, "Should have raised ValueError"
    except ValueError:
        pass  # Expected
    
    try:
        gradebook.record("Alice", "Homework 1", 150)  # Should raise ValueError
        assert False, "Should have raised ValueError"
    except ValueError:
        pass  # Expected
    
    # Test score
    assert gradebook.score("Alice", "Homework 1") == 85
    assert gradebook.score("Bob", "Homework 1") == 92
    assert gradebook.score("Alice", "Exam 1") is None  # No score recorded
    
