// s5_expr.js - Expression evaluator with + - * / operations

/**
 * Evaluates a mathematical expression containing +, -, *, / operators
 * @param {string} expr - The expression to evaluate
 * @returns {number} - The result of the evaluation
 */
function evaluate(expr) {
    // Remove all spaces
    expr = expr.replace(/\s/g, '');
    
    // Check for empty expression
    if (expr === '') {
        throw new Error('Empty expression');
    }
    
    // Check for invalid characters
    if (!/^[0-9+\-*/.()]+$/.test(expr)) {
        throw new Error('Invalid characters in expression');
    }
    
    // Simple recursive descent parser for expressions
    let pos = 0;
    
    function parseExpression() {
        let result = parseTerm();
        
        while (pos < expr.length && (expr[pos] === '+' || expr[pos] === '-')) {
            const operator = expr[pos];
            pos++;
            const right = parseTerm();
            if (operator === '+') {
                result += right;
            } else {
                result -= right;
            }
        }
        
        return result;
    }
    
    function parseTerm() {
        let result = parseFactor();
        
        while (pos < expr.length && (expr[pos] === '*' || expr[pos] === '/')) {
            const operator = expr[pos];
            pos++;
            const right = parseFactor();
            if (operator === '*') {
                result *= right;
            } else {
                if (right === 0) {
                    throw new Error('Division by zero');
                }
                result /= right;
            }
        }
        
        return result;
    }
    
    function parseFactor() {
        if (pos >= expr.length) {
            throw new Error('Unexpected end of expression');
        }
        
        // Handle unary minus
        if (expr[pos] === '-') {
            pos++;
            return -parseFactor();
        }
        
        // Handle parentheses
        if (expr[pos] === '(') {
            pos++;
            const result = parseExpression();
            if (pos >= expr.length || expr[pos] !== ')') {
                throw new Error('Mismatched parentheses');
            }
            pos++;
            return result;
        }
        
        // Parse number
        let start = pos;
        while (pos < expr.length && /[0-9.]/.test(expr[pos])) {
            pos++;
        }
        
        if (start === pos) {
            throw new Error('Unexpected character: ' + expr[pos]);
        }
        
        return parseFloat(expr.substring(start, pos));
    }
    
    const result = parseExpression();
    
    // Check if we've consumed the entire expression
    if (pos < expr.length) {
        throw new Error('Unexpected character: ' + expr[pos]);
    }
    
    return result;
}

