    // Only add if text is not empty
    if (taskText !== '') {
        // Create new list item
        const li = document.createElement('li');
        li.className = 's9-card';
        li.textContent = taskText;
        
        // Add to the To Do list
        todoList.appendChild(li);
        
        // Clear the input
        newTaskInput.value = '';
    }
}

