  console.assert(false, "Should have thrown an error for empty rows");
} catch (e) {
  console.assert(e.message === "rows cannot be empty", "Should throw correct error for empty rows");
}

try {
  new Matrix([[], [1, 2]]);
  console.assert(false, "Should have thrown an error for empty rows");
} catch (e) {
  console.assert(e.message === "rows cannot be empty", "Should throw correct error for empty rows");
}

try {
  new Matrix([[1, 2], [1, 2, 3]]);
  console.assert(false, "Should have thrown an error for different row lengths");
} catch (e) {
