        const newRow = [];
        for (let j = 0; j < otherShape[1]; j++) {
          let sum = 0;
          for (let k = 0; k < thisShape[1]; k++) {
            sum += this.get(i, k) * x.get(k, j);
          }
          newRow.push(sum);
        }
        resultRows.push(newRow);
      }
      return new Matrix(resultRows);
    } else {
      throw new Error("mul(x) expects a number or Matrix as argument");
    }
  }
}

