            pos++;
        }
        
        if (start === pos) {
            throw new Error('Unexpected character: ' + expr[pos]);
        }
        
        return parseFloat(expr.substring(start, pos));
    }
    
    const result = parseExpression();
    
    // Check if we've consumed the entire expression
    if (pos < expr.length) {
        throw new Error('Unexpected character: ' + expr[pos]);
    }
    
    return result;
}

