  }
  
  if (cache.size() === 2) {
    console.log('PASS: Size is correct');
  } else {
    console.log('FAIL: Size is incorrect');
  }
  
  // Test 3: Eviction
  cache.set('c', 3);
  
  if (cache.get('b') === undefined) {
    console.log('PASS: Least recently used item was evicted');
  } else {
