]);
const transposed = testMatrix.transpose();
console.assert(transposed.shape()[0] === 3 && transposed.shape()[1] === 2, "Transposed matrix should be 3x2");
console.assert(transposed.get(0, 0) === 1, "Element at (0,0) should be 1");
