                    # Recalculate scores based on remaining percentages
                    dropped_scores = [p/100 * max_points for p, max_points in zip(dropped_percentages, category_max_points[category]) if p/100 * max_points > 0]
                    category_scores[category] = dropped_scores
                    category_max_points[category] = [max_points for p, max_points in zip(percentages, category_max_points[category]) if p/100 * max_points > 0][n:]

        # Calculate weighted average
        total_weighted_percentage = 0
        total_weight = 0

        for category, scores in category_scores.items():
            if not scores:
                continue
            score = sum(scores)
            max_points = sum(category_max_points[category])
            percentage = (score / max_points) * 100
            weight = self.categories[category]

            total_weighted_percentage += percentage * weight
            total_weight += weight

        # Normalize by total weight
        if total_weight == 0:
            return None
