        // Load doing items
        state.doing.forEach(taskText => {
            addTaskToColumn(taskText, doingList);
        });

        // Load done items
        state.done.forEach(taskText => {
            addTaskToColumn(taskText, doneList);
        });

        // Update counters
        updateCounters();
    }
}

// Helper function to add a task to a specific column
