    if (typeof x === 'number') {
      // Scalar multiplication
      const resultRows = [];
      const thisShape = this.shape();
      for (let i = 0; i < thisShape[0]; i++) {
        const newRow = [];
        for (let j = 0; j < thisShape[1]; j++) {
          newRow.push(this.get(i, j) * x);
