  multiLibrary.addBook('123', 'The Great Gatsby');
  multiLibrary.addBook('456', '1984');
  multiLibrary.addBook('789', 'To Kill a Mockingbird');
  const result3 = shelfLine(multiLibrary);
  // Titles should be sorted alphabetically
