    if (thisShape[0] !== otherShape[0] || thisShape[1] !== otherShape[1]) {
      return false;
    }

    // Check each element with epsilon tolerance
    for (let i = 0; i < thisShape[0]; i++) {
      for (let j = 0; j < thisShape[1]; j++) {
        const diff = Math.abs(this.get(i, j) - other.get(i, j));
        if (diff > eps) {
